mapper.select:
     select count(1) from ww_message m where m.m_read = '0'
	   and exists (
	     select distinct p.p_id from ww_sys_user su,ww_product p,ww_sys_user_product_ref supr
	       where su.login_name = supr.user_id and p.p_id = supr.product_id and m.product=p.p_id
	         and su.login_name = #{loginName}
	   )

   select t.*,(sysdate-to_date(t.create_time,'yyyy-MM-dd HH24:mi:ss'))*24*60*60 m_time_sec from (
     select * from ww_message m where
	   exists (
	     select distinct p.p_id from ww_sys_user su,ww_product p,ww_sys_user_product_ref supr
	       where su.login_name = supr.user_id and p.p_id = supr.product_id and m.product=p.p_id
	         and su.login_name = #{loginName}
	   )
     order by m.m_read,m.create_time desc
   ) t where rownum  <=  #{fetchRowNum}

       select m.*,UNIX_TIMESTAMP(SYSDATE()) - UNIX_TIMESTAMP(STR_TO_DATE(m.create_time,'%Y-%m-%d %H:%i:%s')) m_time_sec from ww_message m where
	     exists (
	       select distinct p.p_id from ww_sys_user su,ww_product p,ww_sys_user_product_ref supr
	         where su.login_name = supr.user_id and p.p_id = supr.product_id and m.product=p.p_id
	           and su.login_name = #{loginName}
	     )
       order by m.m_read,m.create_time desc
       limit #{fetchRowNum}

	select * from ww_message m where 1=1
	
		and exists (
    	  select distinct p.p_id from ww_sys_user su,ww_product p,ww_sys_user_product_ref supr
      	    where su.login_name = supr.user_id and p.p_id = supr.product_id and m.product=p.p_id
        	  and su.login_name = #{loginName}
        )
    
    
		and id = #{id}
	
	
		and product = #{product}
	
	
		and instr(m_level,#{lMLevel}) > 0
	
	
		and m_read = #{mRead}
	
	order by create_time desc

